import itertools, json, sys
chars = list('ABCDEFGHJK')  # note: no I, no L, no M, etc.
# constraints
prohibited = {
    0: set(['A','E','F']),
    1: set(['B','E','G']),
    2: set(['C','E','H']),
    3: set(['D','E','J']),
}
solutions = []
for combo in itertools.product(chars, repeat=4):
    # exactly two K's
    if combo.count('K') != 2:
        continue
    ok = True
    for i,ch in enumerate(combo):
        if ch in prohibited[i]:
            ok=False
            break
    if ok:
        solutions.append(''.join(combo))
print(len(solutions))
print(solutions[:50])

allowed = list('ABCDEFGHIJK')
# Actually allowed letters are A B C D E F G H J K (no I) but we include J,K.
allowed = ['A','B','C','D','E','F','G','H','J','K']
attempts = ['JACK','ABCD','EFGH','BCAE']
valid = []
for a in allowed:
    for b in allowed:
        for c in allowed:
            for d in allowed:
                cand = a+b+c+d
                ok=True
                for att in attempts:
                    cnt=sum(1 for x,y in zip(cand, att) if x==y)
                    if cnt!=0:
                        ok=False
                        break
                if ok:
                    valid.append(cand)
print('total', len(valid))
print(valid[:100])

